// swift-tools-version: 6.2
import PackageDescription

// The Rust key core (rust/srssly-keys-ffi) for the app. Both parts are
// generated by scripts/build-rust-ios.sh and not committed:
//  - SrsslyKeysFFI.xcframework: the static library and its C header.
//  - Sources/SrsslyKeys/SrsslyKeys.swift: UniFFI's Swift bindings.
let package = Package(
    name: "SrsslyKeys",
    platforms: [.iOS(.v26)],
    products: [
        .library(name: "SrsslyKeys", targets: ["SrsslyKeys"]),
    ],
    targets: [
        .binaryTarget(name: "SrsslyKeysFFI", path: "SrsslyKeysFFI.xcframework"),
        .target(name: "SrsslyKeys", dependencies: ["SrsslyKeysFFI"]),
    ]
)
